	set_temp_variable = { cannibalism_inherited_larder_route = cannibalism_larder_route }
	set_temp_variable = { cannibalism_inherited_network_route = cannibalism_network_route }
	set_temp_variable = { cannibalism_inherited_larder = cannibalism_larder }
	set_temp_variable = { cannibalism_inherited_frenzy = cannibalism_frenzy }
	set_temp_variable = { cannibalism_inherited_alignment = cannibalism_network_alignment }
	set_temp_variable = { cannibalism_inherited_consumed_population = cannibalism_consumed_population }
	set_temp_variable = { cannibalism_inherited_consumed_population_k = cannibalism_consumed_population_k }
	set_temp_variable = { cannibalism_inherited_warlord_origin = cannibalism_warlord_origin }
	set_temp_variable = { cannibalism_inherited_warlord_region = cannibalism_warlord_region }
	set_temp_variable = { cannibalism_inherited_warlord_name_index = cannibalism_warlord_name_index }
	set_temp_variable = { cannibalism_inherited_warlord_slot_index = cannibalism_warlord_slot_index }
	set_temp_variable = { cannibalism_inherited_warlord_personality = cannibalism_warlord_personality }

	set_temp_variable = { cannibalism_inherited_origin_island = 0 }
	set_temp_variable = { cannibalism_inherited_origin_siege = 0 }
	set_temp_variable = { cannibalism_inherited_origin_march = 0 }
	if = { limit = { has_country_flag = cannibalism_origin_island_host } set_temp_variable = { cannibalism_inherited_origin_island = 1 } }
	else_if = { limit = { has_country_flag = cannibalism_origin_siege_commune } set_temp_variable = { cannibalism_inherited_origin_siege = 1 } }
	else_if = { limit = { has_country_flag = cannibalism_origin_march_host } set_temp_variable = { cannibalism_inherited_origin_march = 1 } }
}

cannibalism_create_unified_country_from_selected_host = {
	set_temp_variable = { cannibalism_unified_creation_result = 0 }
	if = {
		limit = { cannibalism_selected_unification_host_is_valid = yes }
		event_target:cannibalism_unification_host = {
			save_event_target_as = cannibalism_runtime_migration_source_country
			save_event_target_as = technology_union_donor
			capital_scope = { save_event_target_as = cannibalism_unification_capital_state }
			cannibalism_capture_current_warlord_inheritance = yes
			set_temp_variable = { cannibalism_unification_host_was_human = 0 }
			if = { limit = { is_ai = no } set_temp_variable = { cannibalism_unification_host_was_human = 1 } }
		}

		# The public flag is set before CBL, its leader, portrait, name, or tree
		# can become visible to any player-facing system.
		set_global_flag = cannibalism_reveal_complete
		set_global_flag = cannibalism_evolution_iii_active
		clr_global_flag = cannibalism_scenario_convergence_contract
		clr_global_flag = cannibalism_convergence_active
		clr_global_flag = cannibalism_convergence_broken
		clr_global_flag = cannibalism_unification_pending
		clr_global_flag = cannibalism_evolution_iii_transition_due
		set_variable = { global.cannibalism_global_stage = constant:cannibalism_global_stage.unified }
		clear_variable = global.cannibalism_convergence_due_date
		clear_variable = global.cannibalism_convergence_rebuild_date

		event_target:cannibalism_unification_capital_state = {
			set_state_owner_to = CBL
			set_state_controller_to = CBL
		}
		CBL = {
			union_compatible_researched_technologies_from_donor = yes
			set_technology = { elephantry = 1 popup = no }
			set_research_slots = constant:cannibalism_unification.starting_research_slots
			set_capital = { state = event_target:cannibalism_unification_capital_state }
			set_politics = { ruling_party = neutrality elections_allowed = no }
			set_variable = { cannibalism_integrated_named_commander_count = 1 }
			set_variable = { cannibalism_integrated_servant_count = 0 }
			set_country_flag = cannibalism_unified_country
			set_country_flag = cannibalism_unified_decisions_open
			set_country_flag = cannibalism_unified_focus_tree_available
			set_country_flag = cannibalism_reveal_host
			load_focus_tree = { tree = cannibalism_unified_focus_tree keep_completed = no }
			cannibalism_unified_initialize_decision_values = yes
			cannibalism_apply_unified_country_ai_strategy = yes
			cannibalism_register_current_country_actor = yes
			cannibalism_apply_inherited_host_identity_to_cbl = yes
			cannibalism_create_current_warlord_templates = yes
			cannibalism_open_inherited_warlord_recruitment = yes
			country_lock_all_division_template = yes
			if = { limit = { NOT = { has_idea = cannibalism_unified_command_burden } } add_ideas = cannibalism_unified_command_burden }
				add_country_leader_role = {
				character = CBL_hannibal
				promote_leader = yes
				country_leader = {
					ideology = ritual_predation
					traits = { cannibalism_hannibal_network_command }
				}
			}
			add_named_threat = { threat = constant:cannibalism_unification.reveal_world_tension name = cannibalism_reveal_world_tension }
		}

		if = {
			limit = { check_variable = { cannibalism_unification_host_was_human > 0 } }
			event_target:cannibalism_unification_host = {
				cannibalism_achievement_capture_current_player_ledger = yes
				humanitarian_achievement_record_tag_switch = yes
			}
			CBL = {
				cannibalism_achievement_apply_captured_player_ledger = yes
				humanitarian_achievement_record_tag_switch = yes
				set_country_flag = achievement_cannibalism_player_unification_host
				change_tag_from = event_target:cannibalism_unification_host
			}
		}

		CBL = {
			save_event_target_as = cannibalism_runtime_migration_destination_country
			cannibalism_migrate_runtime_references_to_unified_country = yes
			set_variable = { cannibalism_integration_name_index = cannibalism_inherited_warlord_name_index }
			set_variable = { cannibalism_integration_origin = cannibalism_inherited_warlord_origin }
			set_variable = { cannibalism_integration_region = cannibalism_inherited_warlord_region }
			set_variable = { cannibalism_integration_slot_index = cannibalism_inherited_warlord_slot_index }
			set_variable = { cannibalism_integration_personality = cannibalism_inherited_warlord_personality }
			set_variable = { cannibalism_integration_disposition = constant:cannibalism_warlord_disposition.host_commander }
			cannibalism_record_integrated_warlord_slot = yes
			cannibalism_create_integrated_warlord_commander = yes
		}

		# Join the selected host's existing wars before annexing it, so the new
		# country cannot shed the player's active fronts during the transfer.
		event_target:cannibalism_unification_host = {
			every_enemy_country = {
				CBL = {
					add_to_war = {
						targeted_alliance = event_target:cannibalism_unification_host
						enemy = PREV
						hostility_reason = ally
					}
				}
			}
			cannibalism_prepare_current_warlord_slot_for_unification = yes
		}
		CBL = {
			annex_country = {
				target = event_target:cannibalism_unification_host
				transfer_troops = yes
			}
			save_global_event_target_as = cannibalism_unification_host
			save_global_event_target_as = cannibalism_latest_actor
			cannibalism_select_current_country_as_pulse_anchor = yes
			set_temp_variable = { cannibalism_evolution_stage_to_record = constant:cannibalism_event.evolution_iii_stage }
			cannibalism_record_current_evolution = yes
			set_variable = { global.cannibalism_unification_host_generation = cannibalism_actor_generation }
			set_temp_variable = { cannibalism_chaos_change = constant:cannibalism_delta.reveal_chaos }
			set_temp_variable = { cannibalism_chaos_reason = constant:chaos_meter_history_reason.special.cannibalism_reveal }
			cannibalism_apply_chaos_change = yes
			cannibalism_emit_reveal_super_event = yes
			country_event = { id = chaosx.nr14.70 hours = @CANNIBALISM_REVEAL_HOST_EVENT_HOURS }
			news_event = { id = chaosx.news.90 hours = @CANNIBALISM_REVEAL_NEWS_HOURS }
		}

		# Rebuild the response roster at reveal so a warlord created during the
		# warning window cannot escape submission, autonomy, or resistance merely
		# because it was absent from the original convergence snapshot.
		resize_array = { global.cannibalism_convergence_actor_countries = 0 }
		for_each_scope_loop = {
			array = global.cannibalism_actor_countries
			if = {
				limit = {
					exists = yes
					is_cannibalism_warlord_country = yes
					NOT = { tag = CBL }
					NOT = { has_capitulated = yes }
				}
				set_country_flag = cannibalism_pending_absorption
				set_country_flag = cannibalism_convergence_participant
				add_to_array = { array = global.cannibalism_convergence_actor_countries value = THIS }
				country_event = { id = chaosx.nr14.71 hours = @CANNIBALISM_WARLORD_RESPONSE_HOURS }
			}
		}
		set_temp_variable = { cannibalism_unified_creation_result = 1 }
	}
}

cannibalism_absorb_current_warlord_into_unified_host = {
	set_temp_variable = { cannibalism_absorption_result = 0 }
	if = {
		limit = {
			is_cannibalism_warlord_country = yes
			has_country_flag = cannibalism_pending_absorption
			cannibalism_has_valid_unification_destination = yes
		}
		save_event_target_as = cannibalism_runtime_migration_source_country
		save_event_target_as = cannibalism_absorbed_warlord
		save_event_target_as = technology_union_donor
		cannibalism_capture_current_warlord_inheritance = yes
		set_temp_variable = { cannibalism_absorbed_warlord_was_human = 0 }
		if = { limit = { is_ai = no } set_temp_variable = { cannibalism_absorbed_warlord_was_human = 1 } }
		event_target:cannibalism_unification_host = {
			save_event_target_as = cannibalism_runtime_migration_destination_country
			cannibalism_migrate_runtime_references_to_unified_country = yes
		}
		if = {
			limit = { check_variable = { cannibalism_runtime_migration_result > 0 } }
			cannibalism_add_current_warlord_larder_to_unified_host = yes
			event_target:cannibalism_unification_host = {
				union_compatible_researched_technologies_from_donor = yes
				set_variable = { cannibalism_integration_name_index = cannibalism_inherited_warlord_name_index }
				set_variable = { cannibalism_integration_origin = cannibalism_inherited_warlord_origin }
				set_variable = { cannibalism_integration_region = cannibalism_inherited_warlord_region }
				set_variable = { cannibalism_integration_slot_index = cannibalism_inherited_warlord_slot_index }
				set_variable = { cannibalism_integration_personality = cannibalism_inherited_warlord_personality }
				set_variable = { cannibalism_integration_disposition = cannibalism_requested_warlord_disposition }
				cannibalism_apply_absorbed_warlord_inheritance_to_unified_host = yes
				cannibalism_record_integrated_warlord_slot = yes
				if = {
					limit = {
						OR = {
							check_variable = { cannibalism_requested_warlord_disposition = constant:cannibalism_warlord_disposition.retained_commander }
							check_variable = { cannibalism_requested_warlord_disposition = constant:cannibalism_warlord_disposition.host_commander }
						}
					}
					cannibalism_create_integrated_warlord_commander = yes
					add_to_variable = { cannibalism_integrated_named_commander_count = 1 }
				}
				else_if = {
					limit = { check_variable = { cannibalism_requested_warlord_disposition = constant:cannibalism_warlord_disposition.disposable_servant } }
					cannibalism_create_integrated_warlord_servant = yes
					add_to_variable = { cannibalism_integrated_servant_count = 1 }
				}
			}
			every_enemy_country = {
				limit = { NOT = { tag = event_target:cannibalism_unification_host } }
				event_target:cannibalism_unification_host = {
					add_to_war = {
						targeted_alliance = event_target:cannibalism_absorbed_warlord
						enemy = PREV
						hostility_reason = ally
					}
				}
			}
			if = {
				limit = { check_variable = { cannibalism_absorbed_warlord_was_human > 0 } }
				event_target:cannibalism_absorbed_warlord = {
					cannibalism_achievement_capture_current_player_ledger = yes
					humanitarian_achievement_record_tag_switch = yes
				}
				event_target:cannibalism_unification_host = {
					cannibalism_achievement_apply_captured_player_ledger = yes
					humanitarian_achievement_record_tag_switch = yes
					change_tag_from = event_target:cannibalism_absorbed_warlord
				}
			}
			cannibalism_prepare_current_warlord_slot_for_unification = yes
			event_target:cannibalism_unification_host = {
				annex_country = {
					target = event_target:cannibalism_absorbed_warlord
					transfer_troops = yes
				}
				add_to_variable = { cannibalism_integrated_warlord_count = 1 }
			}
			set_temp_variable = { cannibalism_absorption_result = 1 }
		}
	}
}

cannibalism_create_wendigo_unification_from_selected_hosts = {
	set_temp_variable = { cannibalism_wendigo_unification_result = 0 }
	if = {
		limit = {
			cannibalism_selected_wendigo_merge_host_is_valid = yes
			cannibalism_selected_unification_host_is_valid = yes
		}
		event_target:cannibalism_unification_host = {
			save_event_target_as = cannibalism_primary_warlord_donor
			cannibalism_capture_current_warlord_inheritance = yes
			set_temp_variable = { cannibalism_primary_warlord_donor_was_human = 0 }
			if = { limit = { is_ai = no } set_temp_variable = { cannibalism_primary_warlord_donor_was_human = 1 } }
		}
		event_target:cannibalism_wendigo_merge_host = {
			set_temp_variable = { cannibalism_wendigo_merge_host_was_human = 0 }
			if = { limit = { is_ai = no } set_temp_variable = { cannibalism_wendigo_merge_host_was_human = 1 } }
		}
		set_temp_variable = { cannibalism_primary_warlord_donor_can_be_absorbed = 1 }
		if = {
			limit = {
				check_variable = { cannibalism_primary_warlord_donor_was_human > 0 }
				check_variable = { cannibalism_wendigo_merge_host_was_human > 0 }
			}
			set_temp_variable = { cannibalism_primary_warlord_donor_can_be_absorbed = 0 }
			# The nonabsorbed human retains all local Larder until the explicit
			# response choice; only route identity is inherited at reveal.
			set_temp_variable = { cannibalism_inherited_larder = 0 }
		}

		# The reveal flag precedes every transformed country, leader, portrait,
		# focus, decision, cosmetic, report, news, or audio-facing operation.
		set_global_flag = cannibalism_reveal_complete
		set_global_flag = cannibalism_evolution_iii_active
		set_global_flag = achievement_cannibalism_wendigo_merge_occurred
		clr_global_flag = cannibalism_scenario_convergence_contract
		set_global_flag = cannibalism_wendigo_route_active
		clr_global_flag = cannibalism_convergence_active
		clr_global_flag = cannibalism_convergence_broken
		clr_global_flag = cannibalism_unification_pending
		clr_global_flag = cannibalism_evolution_iii_transition_due
		set_variable = { global.cannibalism_global_stage = constant:cannibalism_global_stage.wendigo_merged }
		clear_variable = global.cannibalism_convergence_due_date
		clear_variable = global.cannibalism_convergence_rebuild_date

		event_target:cannibalism_wendigo_merge_host = {
			cannibalism_prepare_wendigo_merge_identity = yes
		}
		if = {
			limit = {
				check_variable = { cannibalism_primary_warlord_donor_was_human > 0 }
				check_variable = { cannibalism_wendigo_merge_host_was_human < 1 }
			}
			event_target:cannibalism_primary_warlord_donor = {
				cannibalism_achievement_capture_current_player_ledger = yes
				humanitarian_achievement_record_tag_switch = yes
			}
			event_target:cannibalism_wendigo_merge_host = {
				cannibalism_achievement_apply_captured_player_ledger = yes
				humanitarian_achievement_record_tag_switch = yes
				change_tag_from = event_target:cannibalism_primary_warlord_donor
			}
		}

		cannibalism_absorb_primary_warlord_donor_into_wendigo = yes
		event_target:cannibalism_wendigo_merge_host = {
			set_variable = { global.cannibalism_unification_host_generation = cannibalism_actor_generation }
			set_temp_variable = { cannibalism_evolution_stage_to_record = constant:cannibalism_event.evolution_iii_stage }
			cannibalism_record_current_evolution = yes
			set_temp_variable = { cannibalism_chaos_change = constant:cannibalism_delta.reveal_chaos }
			set_temp_variable = { cannibalism_chaos_reason = constant:chaos_meter_history_reason.special.cannibalism_reveal }
			cannibalism_apply_chaos_change = yes
			cannibalism_emit_reveal_super_event = yes
		}
		cannibalism_create_initial_wendigo_anchors = yes
		event_target:cannibalism_wendigo_merge_host = { cannibalism_load_wendigo_focus_overlay = yes }
		cannibalism_build_wendigo_warlord_response_roster = yes
		event_target:cannibalism_wendigo_merge_host = {
			country_event = { id = chaosx.nr14.72 hours = @CANNIBALISM_WENDIGO_REVEAL_EVENT_HOURS }
			news_event = { id = chaosx.news.91 hours = @CANNIBALISM_WENDIGO_REVEAL_NEWS_HOURS }
		}
		clr_global_flag = cannibalism_wendigo_transformation_pending
		set_temp_variable = { cannibalism_wendigo_unification_result = 1 }
	}
}

cannibalism_prepare_wendigo_merge_identity = {
	set_country_flag = cannibalism_wendigo_hannibal_country
	set_country_flag = cannibalism_wendigo_transformation_prelock
	set_country_flag = cannibalism_unified_decisions_open
	set_country_flag = cannibalism_wendigo_focus_overlay_available
	set_variable = { cannibalism_country_stage = constant:cannibalism_country_stage.wendigo_merged }
	set_variable = { cannibalism_wendigo_transformation_stage = constant:cannibalism_wendigo_stage.prelock }
	set_variable = { cannibalism_wendigo_transformation_progress = constant:cannibalism_wendigo_merge.starting_progress }
	set_variable = { cannibalism_wendigo_winter_victories = 0 }
	clear_array = global.cannibalism_wendigo_victory_countries
	set_variable = { cannibalism_wendigo_broken_anchor_count = 0 }
	set_variable = { cannibalism_wendigo_trained_pack_count = 0 }
	set_variable = { cannibalism_wendigo_focus_pack_capacity_bonus = constant:cannibalism_meter.min }
	set_variable = { cannibalism_wendigo_pack_capacity = constant:cannibalism_wendigo_decision.train_pack_base_cap }
	set_cosmetic_tag = ZZZ_CANNIBALISM_HANNIBAL
	if = {
		limit = { NOT = { is_in_array = { array = global.cannibalism_actor_countries value = THIS } } }
		cannibalism_register_current_country_actor = yes
	}
	else_if = {
		limit = { NOT = { has_variable = cannibalism_actor_generation } }
		cannibalism_register_current_country_actor = yes
	}
	cannibalism_apply_inherited_host_identity_to_cbl = yes
	add_to_variable = { cannibalism_unified_authority = constant:cannibalism_wendigo_merge.authority_transition_gain }
	clamp_variable = {
		var = cannibalism_unified_authority
		min = constant:cannibalism_meter.min
		max = constant:cannibalism_meter.max
	}
	cannibalism_create_current_warlord_templates = yes
	cannibalism_wendigo_focus_preserve_pack_contract = yes
	cannibalism_open_inherited_warlord_recruitment = yes
	cannibalism_open_wendigo_inherited_cannibal_recruitment = yes
	if = { limit = { has_idea = cannibalism_wendigo_winter_feeding_network } remove_ideas = cannibalism_wendigo_winter_feeding_network }
	if = { limit = { has_idea = cannibalism_wendigo_locked_terminal_form } remove_ideas = cannibalism_wendigo_locked_terminal_form }
	if = { limit = { NOT = { has_idea = cannibalism_wendigo_conjoined_hunger } } add_ideas = cannibalism_wendigo_conjoined_hunger }
	if = { limit = { has_character = ZZZ_leader } retire_character = ZZZ_leader }
	add_country_leader_role = {
		character = ZZZ_hannibal_wendigo
		promote_leader = yes
		country_leader = {
			ideology = ritual_predation
			traits = { cannibalism_hannibal_wendigo_command }
		}
	}
	add_named_threat = { threat = constant:cannibalism_wendigo_merge.reveal_world_tension name = cannibalism_wendigo_reveal_world_tension }
	save_global_event_target_as = cannibalism_wendigo_merge_host
	save_global_event_target_as = cannibalism_unification_host
	save_global_event_target_as = cannibalism_latest_actor
	cannibalism_select_current_country_as_pulse_anchor = yes
}

cannibalism_migrate_runtime_references_to_unified_country = {
	# Contract: cannibalism_runtime_migration_source_country and
	# cannibalism_runtime_migration_destination_country must both be valid
	# regular event targets. Never infer the destination from ROOT: absorption
	# runs from the responding warlord's event scope.
	set_temp_variable = { cannibalism_runtime_migration_result = 0 }
	# The spread owner validates all nine aligned arrays, updates both country
	# directions and exact state metadata, then rebuilds every derived cache.
	cannibalism_migrate_spread_entries_between_countries = yes
	if = {
		limit = { check_variable = { cannibalism_spread_migration_result > 0 } }
		for_each_scope_loop = {
			array = global.cannibalism_node_states
			if = {
				limit = {
					has_variable = cannibalism_node_source_country
					check_variable = {
						var = cannibalism_node_source_country
						value = event_target:cannibalism_runtime_migration_source_country
						compare = equals
					}
				}
				set_variable = { cannibalism_node_source_country = event_target:cannibalism_runtime_migration_destination_country }
				set_variable = { cannibalism_node_source_country_generation = event_target:cannibalism_runtime_migration_destination_country.cannibalism_actor_generation }
			}
		}
		for_each_scope_loop = {
			array = global.cannibalism_actor_countries
			if = {
				limit = {
					has_variable = cannibalism_external_infection_source
					check_variable = {
						var = cannibalism_external_infection_source
						value = event_target:cannibalism_runtime_migration_source_country
						compare = equals
					}
				}
				set_variable = { cannibalism_external_infection_source = event_target:cannibalism_runtime_migration_destination_country }
			}
		}
		set_temp_variable = { cannibalism_runtime_migration_result = 1 }
	}
}

cannibalism_migrate_spread_entries_between_countries = {
	set_temp_variable = { cannibalism_spread_migration_result = 0 }
	cannibalism_validate_spread_queue = yes
	if = {
		limit = {
			check_variable = { cannibalism_spread_queue_validation_result > 0 }
			has_event_target = cannibalism_runtime_migration_source_country
			has_event_target = cannibalism_runtime_migration_destination_country
			event_target:cannibalism_runtime_migration_source_country = { exists = yes }
			event_target:cannibalism_runtime_migration_destination_country = {
				exists = yes
				has_variable = cannibalism_actor_generation
				check_variable = { cannibalism_actor_generation > 0 }
				NOT = { tag = event_target:cannibalism_runtime_migration_source_country }
			}
		}
		set_temp_variable = { cannibalism_spread_migration_destination_generation = event_target:cannibalism_runtime_migration_destination_country.cannibalism_actor_generation }
		event_target:cannibalism_runtime_migration_source_country = {
			clear_variable = cannibalism_outbound_spread_count
			clear_variable = cannibalism_inbound_spread_count
			clr_country_flag = cannibalism_foreign_seeding_active
			clr_country_flag = cannibalism_foreign_route_warning_active
		}
		set_temp_variable = { cannibalism_spread_queue_index = 0 }
		while_loop_effect = {
			limit = {
				check_variable = {
					var = cannibalism_spread_queue_index
					value = global.cannibalism_spread_queue_status_entries^num
					compare = less_than
				}
			}
			if = {
				limit = { cannibalism_loaded_spread_status_is_live = yes }
				set_temp_variable = { cannibalism_spread_migration_requested_id = global.cannibalism_spread_queue_id_entries^cannibalism_spread_queue_index }
				cannibalism_load_spread_entry_context = yes
				set_temp_variable = { cannibalism_spread_migration_source_match = 0 }
				set_temp_variable = { cannibalism_spread_migration_target_match = 0 }
				if = {
					limit = {
						var:global.cannibalism_spread_queue_source_country_entries^cannibalism_spread_queue_index = {
							tag = event_target:cannibalism_runtime_migration_source_country
						}
					}
					set_temp_variable = { cannibalism_spread_migration_source_match = 1 }
				}
				if = {
					limit = {
						var:global.cannibalism_spread_queue_target_country_entries^cannibalism_spread_queue_index = {
							tag = event_target:cannibalism_runtime_migration_source_country
						}
					}
					set_temp_variable = { cannibalism_spread_migration_target_match = 1 }
				}
				if = {
					limit = {
						check_variable = { cannibalism_spread_migration_source_match > 0 }
						check_variable = { var = cannibalism_expected_spread_id value = cannibalism_spread_migration_requested_id compare = equals }
					}
					event_target:cannibalism_spread_target_state = {
						set_variable = { cannibalism_inbound_spread_source_country = event_target:cannibalism_runtime_migration_destination_country }
						set_variable = { cannibalism_inbound_spread_source_generation = cannibalism_spread_migration_destination_generation }
					}
					set_variable = { global.cannibalism_spread_queue_source_country_entries^cannibalism_spread_queue_index = event_target:cannibalism_runtime_migration_destination_country }
					set_variable = { global.cannibalism_spread_queue_source_generation_entries^cannibalism_spread_queue_index = cannibalism_spread_migration_destination_generation }
				}
				if = {
					limit = {
						check_variable = { cannibalism_spread_migration_target_match > 0 }
						check_variable = { var = cannibalism_expected_spread_id value = cannibalism_spread_migration_requested_id compare = equals }
					}
					set_variable = { global.cannibalism_spread_queue_target_country_entries^cannibalism_spread_queue_index = event_target:cannibalism_runtime_migration_destination_country }
				}
			}
			add_to_temp_variable = { cannibalism_spread_queue_index = 1 }
		}
		cannibalism_rebuild_spread_pending_ledgers = yes
		if = {
			limit = { check_variable = { cannibalism_spread_queue_validation_result > 0 } }
			set_temp_variable = { cannibalism_spread_migration_result = 1 }
		}
	}
}
